            for ay in (-1, 0, 1):
                if ax == 0 and ay == 0:
                    continue
                tx, ty = nx + ax, ny + ay
                if inb(tx, ty) and (tx, ty) in obstacles:
                    score -= 3

        key = (-(score), dx, dy)  # deterministic tie-break: higher score, then smaller dx,dy? via key
        if best is None or key < best:
            best = key
            best_score = score

    # recover dx,dy from best key
    dx = best[1]
    dy = best[2]
    return [int(dx), int(dy)]

