            new_adv = new_ds - md(ox, oy, tx, ty)
            # Prefer reaching target faster; slight preference for collecting nearer resources.
            collectible = 0
            if (nx, ny) in res:
                collectible = -1000
            # Penalize moving adjacent to obstacles (avoid tight spots).
